{"explanation":"Two functions are inverses when each one undoes the other. On a graph, that means swapping x and y: every point (a, eᵃ) on y = eˣ matches a point (eᵃ, a) on y = ln(x). Swapping coordinates is the same as reflecting across the line y = x, so the graph of ln(x) is the mirror image of eˣ. Move the slider and you'll see that the segment from P to Q always crosses y = x at a right angle, and its midpoint always sits on that line.","manimCode":"const ax = new Axes({
  xRange: [-4, 4, 1], yRange: [-4, 4, 1],
  xLength: 7, yLength: 7, tips: false
});
ax.moveTo([-2.2, 0, 0]);

const expCurve = ax.plot(x => Math.exp(x), { color: BLUE, xRange: [-4, Math.log(4)], numSamples: 300 });
const lnCurve = ax.plot(x => Math.log(x), { color: ORANGE, xRange: [Math.exp(-4), 4], numSamples: 300 });
const idLine = ax.plot(x => x, { color: GRAY, xRange: [-4, 4] });

await scene.play(new Create(ax));
await scene.play(new Create(idLine));
await scene.play(new Create(expCurve));

const expLabel = new MathTex({ latex: 'y = e^x', color: BLUE });
await expLabel.waitForRender();
expLabel.moveTo([4.2, 1.2, 0]);
const idLabel = new MathTex({ latex: 'y = x', color: GRAY });
await idLabel.waitForRender();
idLabel.moveTo([4.2, 0.4, 0]);
await scene.play(new AnimationGroup([new Write(expLabel), new Write(idLabel)]));

// Reflect: morph a copy of e^x into ln(x)
const expCopy = ax.plot(x => Math.exp(x), { color: BLUE, xRange: [-4, Math.log(4)], numSamples: 300 });
scene.add(expCopy);
await scene.play(new Transform(expCopy, lnCurve));
scene.remove(expCopy);
scene.add(lnCurve);

const lnLabel = new MathTex({ latex: 'y = \\ln x', color: ORANGE });
await lnLabel.waitForRender();
lnLabel.moveTo([4.2, -0.4, 0]);
await scene.play(new Write(lnLabel));

// Interactive mirror pair
let a = 0.5;
const P = new Dot({ point: ax.c2p(a, Math.exp(a)), color: BLUE_A });
const Q = new Dot({ point: ax.c2p(Math.exp(a), a), color: ORANGE });
const M = new Dot({ point: ax.c2p((a + Math.exp(a)) / 2, (a + Math.exp(a)) / 2), color: WHITE });
const seg = new Polygon({ vertices: [P.getCenter(), Q.getCenter()], color: YELLOW });
seg.setStrokeWidth(3).setFillOpacity(0);

seg.addUpdater(() => {
  seg.setVertices([ax.c2p(a, Math.exp(a)), ax.c2p(Math.exp(a), a)]);
});
P.addUpdater(() => P.moveTo(ax.c2p(a, Math.exp(a))));
Q.addUpdater(() => Q.moveTo(ax.c2p(Math.exp(a), a)));
M.addUpdater(() => {
  const m = (a + Math.exp(a)) / 2;
  M.moveTo(ax.c2p(m, m));
});

await scene.play(new AnimationGroup([new FadeIn(seg), new FadeIn(P), new FadeIn(Q), new FadeIn(M)]));

let readout = null;
function updateReadout() {
  if (readout) scene.remove(readout);
  const ea = Math.exp(a);
  readout = new VGroup(
    new Text({ text: 'P = (' + a.toFixed(2) + ', ' + ea.toFixed(2) + ')', color: BLUE_A, fontSize: 24 }),
    new Text({ text: 'Q = (' + ea.toFixed(2) + ', ' + a.toFixed(2) + ')', color: ORANGE, fontSize: 24 }),
    new Text({ text: 'swap x and y = reflect', color: YELLOW, fontSize: 22 })
  );
  readout.arrange(DOWN, 0.2);
  readout.moveTo([4.2, -2.3, 0]);
  scene.add(readout);
}
updateReadout();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({
  label: 'a (point on e^x)', min: -3, max: 1.35, value: a, step: 0.01,
  onChange: (v) => { a = v; updateReadout(); }
});
controls.addButton({
  label: 'Sweep',
  onClick: async () => {
    for (let i = 0; i <= 120; i++) {
      a = -3 + (4.35 * i) / 120;
      if (i % 6 === 0) updateReadout();
      await scene.wait(0.03);
    }
    updateReadout();
  }
});

await scene.wait(999999);"}

